"""CRD reference: api/crds/*.yaml (generated by controller-gen from the Go types in api/v1alpha1) -> docs/reference/crds.md."""
from __future__ import annotations

import glob
from pathlib import Path

import yaml

from common import anchor_id, cell, header, scrub


def type_of(s: dict) -> str:
    if s.get("x-kubernetes-int-or-string"):
        return "int or string"
    t = s.get("type", "object")
    if t == "array":
        return f"[]{type_of(s.get('items', {}))}"
    if t == "object" and isinstance(s.get("additionalProperties"), dict):
        return f"map[string]{type_of(s['additionalProperties'])}"
    if s.get("format") and t == "string":
        return f"string ({s['format']})"
    return t


def constraints(s: dict) -> str:
    parts = []
    if "enum" in s:
        parts.append("one of " + ", ".join(f"`{v}`" for v in s["enum"]))
    if "default" in s:
        parts.append(f"default `{s['default']}`")
    for key, label in (("minimum", "min"), ("maximum", "max"), ("minLength", "min length"), ("maxLength", "max length"),
                       ("minItems", "min items"), ("maxItems", "max items")):
        if key in s:
            parts.append(f"{label} {s[key]}")
    if "pattern" in s:
        parts.append(f"pattern `{s['pattern']}`")
    for rule in s.get("x-kubernetes-validations", []):
        if rule.get("message"):
            parts.append(f"rule: {rule['message']}")
    return "; ".join(parts)


def rows(schema: dict, prefix: str, where: str, out: list[tuple[str, str, str, str]]) -> None:
    required = set(schema.get("required", []))
    for name, sub in schema.get("properties", {}).items():
        path = f"{prefix}{name}"
        desc = scrub(sub.get("description"), where)
        out.append((path, type_of(sub) + ("" if name not in required else ", required"), constraints(sub), desc))
        if sub.get("type") == "object":
            rows(sub, path + ".", where, out)
        elif sub.get("type") == "array" and sub.get("items", {}).get("type") == "object":
            rows(sub["items"], path + "[].", where, out)


def render(path: str) -> str:
    crd = yaml.safe_load(Path(path).read_text())
    spec = crd["spec"]
    names = spec["names"]
    kind = names["kind"]
    version = next(v for v in spec["versions"] if v.get("storage"))
    schema = version["schema"]["openAPIV3Schema"]
    where = f"api/crds/{Path(path).name} ({kind})"
    lines = [f"## {kind} {{ #{anchor_id(kind)} }}", ""]
    lines += [scrub(schema.get("description"), where), ""]
    lines += [
        "| | |",
        "|---|---|",
        f"| API version | `{spec['group']}/{version['name']}` |",
        f"| Kind | `{kind}` (list: `{names['listKind']}`) |",
        f"| Resource | `{names['plural']}`" + (f", short name `{'`, `'.join(names['shortNames'])}`" if names.get("shortNames") else "") + " |",
        f"| Scope | {spec['scope']} |",
        f"| Status subresource | {'yes' if 'status' in version.get('subresources', {}) else 'no'} |",
        "",
    ]
    cols = version.get("additionalPrinterColumns", [])
    if cols:
        lines += ["`kubectl get` columns: " + ", ".join(f"{c['name']} (`{c['jsonPath']}`)" for c in cols) + ".", ""]
    for section in ("spec", "status"):
        sub = schema.get("properties", {}).get(section)
        if not sub:
            continue
        out: list[tuple[str, str, str, str]] = []
        rows(sub, f"{section}.", where, out)
        lines += [f"### {kind} {section} {{ #{anchor_id(kind)}-{section} }}", "", scrub(sub.get("description"), where), ""]
        lines += ["| Field | Type | Constraints | Description |", "|---|---|---|---|"]
        for p, t, c, d in out:
            lines.append(f"| `{p}` | {cell(t)} | {cell(c)} | {cell(d)} |")
        lines.append("")
    return "\n".join(lines)


def generate(root: Path) -> dict[str, str]:
    files = sorted(glob.glob(str(root / "api/crds/*.yaml")))
    body = [

        header("api/crds (built from api/v1alpha1)"),
        "# Custom resources",
        "",
        "Kerf installs two cluster-scoped custom resources in the API group `kerf.getkerf.dev`. A `RightsizingPolicy` says "
        "which workloads to rightsize and how; the agent writes a `RightsizingRecommendation` for each workload it manages. "
        "The concepts behind the fields are explained under [Concepts](../concepts/README.md).",
        "",
    ]
    for f in files:
        body.append(render(f))
    return {"docs/reference/crds.md": "\n".join(body).rstrip() + "\n"}
